-- CriaSite · migration 004 · aviso e link de afiliado da Hostinger no guia de hospedagem
-- Acrescenta, entre "Quanto custa" e "Passo a passo para contratar", uma nota de transparência com o link de afiliado.
-- Só altera o guia se ele ainda não foi editado no painel (updated_at IS NULL): edição manual do dono nunca é sobrescrita.
-- Se o guia já tiver sido editado, nada acontece: inclua a nota pelo painel (/admin → Matérias).

SET NAMES utf8mb4;

UPDATE posts
   SET body = '[{"type":"p","text":"Hospedagem é o computador ligado 24 horas por dia onde os arquivos do seu site ficam guardados. A escolha certa depende do tipo de site que você vai ter, não do plano mais caro. Neste guia você vê as opções, o que conferir antes de contratar e como comparar o custo de verdade, incluindo a renovação."},{"type":"h2","text":"Os tipos de hospedagem"},{"type":"h3","text":"Compartilhada"},{"type":"p","text":"Vários sites dividem o mesmo servidor. Resolve bem site institucional, blog e portfólio: o painel já vem pronto e instalar o WordPress leva poucos cliques. É a porta de entrada mais comum."},{"type":"h3","text":"VPS e nuvem"},{"type":"p","text":"Você recebe recursos reservados e mais controle sobre o servidor. Em troca, exige conhecimento técnico ou um suporte que administre o servidor por você. Faz sentido para lojas com muito acesso e sistemas próprios."},{"type":"h3","text":"Construtor de sites"},{"type":"p","text":"Plataformas como Wix e similares vendem a hospedagem e o editor no mesmo pacote. É mais simples de começar, mas dá menos liberdade e costuma ser mais difícil de levar o site para outro lugar depois."},{"type":"h3","text":"WordPress gerenciado"},{"type":"p","text":"A empresa cuida das atualizações, do cache e da segurança do WordPress. Custa mais que a compartilhada e poupa trabalho de manutenção."},{"type":"h2","text":"O que conferir no plano"},{"type":"ul","items":["Certificado SSL gratuito incluído, que dá o cadeado e o HTTPS. O Let''s Encrypt é gratuito e muitas empresas instalam sozinhas.","E-mail com o seu domínio e quantas caixas o plano inclui.","Backup automático: quem faz, com que frequência, se cobra para restaurar.","Onde ficam os servidores. Perto do seu público, a resposta tende a ser mais rápida.","Suporte em português e por qual canal ele atende.","Limites de armazenamento, número de sites e tráfego.","Facilidade para sair: dá para exportar os arquivos e o banco de dados quando você quiser?"]},{"type":"h2","text":"Disponibilidade: quanto tempo o site fica no ar"},{"type":"p","text":"As empresas costumam prometer uma disponibilidade em porcentagem. Uma garantia de 99,9% ao mês ainda permite cerca de 43 minutos fora do ar, porque 0,1% de 30 dias dá esse tempo. Veja também o que a empresa oferece se descumprir a promessa. Para entender o que o navegador recebe quando o site falha, consulte os [códigos de status HTTP](/ferramentas/status-http), como o 500 e o 503."},{"type":"h2","text":"Quanto custa"},{"type":"p","text":"A hospedagem compartilhada de entrada costuma ficar em algumas dezenas de reais por mês. VPS e nuvem custam mais e variam com os recursos. É comum o primeiro período ter um desconto grande e a renovação vir pelo preço cheio, e o desconto maior costuma exigir pagar vários meses adiantados. Os preços mudam com frequência: compare o preço de renovação, não só o da vitrine."},{"type":"h2","text":"Uma nota de transparência"},{"type":"p","text":"O CriaSite é hospedado na Hostinger e participa do programa de afiliados dela. O link a seguir é de afiliado: se você contratar por ele, o CriaSite pode receber uma comissão, sem custo extra para você. Isso não muda os critérios deste guia, que valem para qualquer empresa. Compare as opções antes de decidir e confira os preços e as condições atuais na página do plano. [Ver os planos da Hostinger](https://www.hostinger.com/br?REFERRALCODE=ITPEVSLIN5FP)"},{"type":"h2","text":"Passo a passo para contratar"},{"type":"ol","items":["Defina o tipo de site e o volume de visitas que você espera.","Escolha o tipo de hospedagem que combina com isso.","Compare duas ou três empresas usando a lista de itens acima.","Calcule o custo total de dois anos, já com a renovação.","Contrate no seu nome e com o seu e-mail.","Aponte o domínio para a hospedagem seguindo as instruções do painel. A mudança pode levar algumas horas para valer em todo lugar.","Ative o SSL e teste se o site abre com https."]},{"type":"h2","text":"Erros comuns"},{"type":"ul","items":["Escolher só pelo preço do primeiro mês, sem olhar a renovação.","Contratar VPS sem saber administrar um servidor.","Deixar a conta no nome de quem faz o site, o que pode travar uma mudança no futuro.","Nunca testar o backup, e descobrir que ele não funciona só quando precisa.","Usar um e-mail gratuito genérico no cartão de visita, em vez de um e-mail com o seu domínio."]},{"type":"h2","text":"Perguntas frequentes"},{"type":"h3","text":"Posso trocar de hospedagem depois?"},{"type":"p","text":"Pode. O domínio é separado da hospedagem, e muitas empresas ajudam a migrar o site."},{"type":"h3","text":"Hospedagem grátis vale a pena?"},{"type":"p","text":"Serve para testes. Costuma ter anúncios, limites baixos e endereço sem domínio próprio, o que não passa credibilidade para um negócio."},{"type":"h3","text":"Domínio e hospedagem precisam ser da mesma empresa?"},{"type":"p","text":"Não. Na mesma empresa fica mais simples de gerenciar, mas não é obrigatório. Se quiser rever como escolher o endereço, leia o guia sobre [como escolher o domínio](/guias/como-escolher-o-dominio-do-site)."},{"type":"h3","text":"Preciso de VPS para começar?"},{"type":"p","text":"Para site institucional ou blog, em geral não. A compartilhada atende e custa menos."},{"type":"p","text":"Com o site hospedado, falta dar a cara dele: veja [cores, fonte e favicon](/guias/cores-fonte-e-favicon-do-site) e marque o que já fez na [trilha](/trilha#hospedagem)."},{"type":"p","text":"Leia também: [Site lento? As causas mais comuns e como resolver as imagens](/guias/site-lento-causas-e-como-otimizar-imagens)"}]',
       updated_at = UTC_TIMESTAMP()
 WHERE section = 'guias' AND slug = 'como-escolher-a-hospedagem-do-site' AND updated_at IS NULL;
